import pandas as pd
import numpy as np

class DecisionTree:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth

    def fit(self, X, y):
        self.tree = self._grow_tree(X, y, depth=0)

    def _grow_tree(self, X, y, depth):
        num_samples_per_class = [np.sum(y == i) for i in [0, 1]]
        predicted_class = np.argmax(num_samples_per_class)

        if depth < self.max_depth and y.size > 0:
            best_gini = 1.0
            best_idx, best_thr = None, None

            for idx in range(X.shape[1]):
                thresholds = np.unique(X[:, idx])
                for thr in thresholds:
                    left_y = y[X[:, idx] < thr]
                    right_y = y[X[:, idx] >= thr]
                    if left_y.size == 0 or right_y.size == 0:
                        continue

                    n = len(y)
                    n_l, n_r = len(left_y), len(right_y)
                    gini_l = 1.0 - sum((np.sum(left_y == c) / n_l) ** 2 for c in [0, 1])
                    gini_r = 1.0 - sum((np.sum(right_y == c) / n_r) ** 2 for c in [0, 1])
                    gini = (n_l / n) * gini_l + (n_r / n) * gini_r

                    if gini < best_gini:
                        best_gini = gini
                        best_idx = idx
                        best_thr = thr

            if best_idx is not None:
                left_indices = X[:, best_idx] < best_thr
                left = self._grow_tree(X[left_indices], y[left_indices], depth + 1)
                right = self._grow_tree(X[~left_indices], y[~left_indices], depth + 1)
                return {'feature_idx': best_idx, 'threshold': best_thr, 'left': left, 'right': right}

        return {'predicted_class': predicted_class}

    def predict(self, X):
        return np.array([self._predict(inputs, self.tree) for inputs in X])

    def _predict(self, inputs, tree):
        if 'predicted_class' in tree:
            return tree['predicted_class']
        if inputs[tree['feature_idx']] < tree['threshold']:
            return self._predict(inputs, tree['left'])
        return self._predict(inputs, tree['right'])

def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    X_train = train.drop('target', axis=1).values
    y_train = train['target'].values
    X_test = test.drop('target', axis=1).values

    # Train on a small subset because tree building in Python is slow
    subset = np.random.choice(len(X_train), 1000, replace=False)

    clf = DecisionTree(max_depth=3)
    clf.fit(X_train[subset], y_train[subset])

    y_pred = clf.predict(X_test)

    predictions = pd.DataFrame({"prediction": y_pred})
    predictions.to_csv(output_csv, index=False)
